validate_doc_update:
function(newDoc, oldDoc, userCtx, secObj) {
  if (newDoc._deleted) return;
  var canonicalTypes = {
    "account": true,
    "location": true,
    "employee": true,
    "visit": true,
    "visit_gap": true,
    "opportunity": true,
    "shift_report": true,
    "day_record": true,
    "journal": true,
    "unknown_capture": true,
    "personnel_event": true,
    "prospect": true,
    "site_issue": true,
    "supply_need": true,
    "monthly_summary": true,
    "equipment_request": true,
    "supply_order": true,
    "plan": true,
    "inventory": true,
    "note": true,
    "operator": true
  };
  if (!newDoc.type || !canonicalTypes[newDoc.type]) {
    throw({forbidden: 'Document type must be one of the canonical entity types.'});
  }
  if (newDoc.type !== 'operator' && !newDoc.operator) {
    throw({forbidden: 'Non-operator entity documents require an operator field.'});
  }
}

by_type.map:
function(doc) {
  if (doc._deleted) return;
  emit([doc.type, doc._id], null);
}

by_operator_type.map:
function(doc) {
  if (doc._deleted) return;
  if (typeof doc.operator === 'undefined') return;
  emit([doc.operator, doc.type, doc._id], null);
}

employees_by_site.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'employee') return;
  var status = doc.status || null;
  var value = {name: doc.name || null, person_id: doc.person_id || null, hire_date: doc.hire_date || null};
  function clean(input) {
    if (!input) return '';
    return String(input).replace(/^\s+|\s+$/g, '');
  }
  function stringValues(input) {
    var values = [];
    if (Array.isArray(input)) {
      for (var i = 0; i < input.length; i++) {
        var item = clean(input[i]);
        if (item) values.push(item);
      }
      return values;
    }
    var text = clean(input);
    if (text) values.push(text);
    return values;
  }
  function bareSiteId(input) {
    var text = clean(input).replace(/^"+|"+$/g, '');
    if (text.indexOf('location_') === 0) return text.substr(9);
    if (text.indexOf('site_') === 0) return text.substr(5);
    return text;
  }
  function bareSiteIds(input) {
    var values = stringValues(input);
    var ids = [];
    for (var i = 0; i < values.length; i++) {
      ids.push(bareSiteId(values[i]));
    }
    return ids;
  }
  function dedupe(values) {
    var seen = {};
    var result = [];
    for (var i = 0; i < values.length; i++) {
      var item = values[i];
      var seenKey = '$' + item;
      if (item && !seen[seenKey]) {
        seen[seenKey] = true;
        result.push(item);
      }
    }
    return result;
  }
  var siteIds = bareSiteIds(doc.site_ids);
  if (siteIds.length === 0) {
    siteIds = bareSiteIds(doc.job).concat(bareSiteIds(doc.additional_jobs));
    if (siteIds.length === 0) {
      siteIds = bareSiteIds(doc.sites);
    }
  }
  siteIds = dedupe(siteIds);
  if (siteIds.length === 0) {
    emit([null, status, doc._id], value);
    return;
  }
  for (var i = 0; i < siteIds.length; i++) {
    emit([siteIds[i], status, doc._id], value);
  }
}

employees_by_status.map:
function(doc) {
